#!/usr/bin/env python3
"""
KEYHAVEN navbar update: theme toggle + profile dropdown fix (4 files).
Usage (from your project root, the folder with package.json):
    python3 install_navbar_update.py .
A .bak copy is saved next to every file it replaces. No database changes needed.
"""
import base64, os, shutil, sys, zlib
FILES = {"src/lib/theme.ts": "", "src/app/layout.tsx": "", "src/components/site/Header.tsx": "", "src/components/site/ThemeToggle.tsx": ""}
def main():
    if len(sys.argv) != 2: sys.exit('Usage: python3 install_navbar_update.py "<project root>"')
    root = sys.argv[1]
    if not os.path.isfile(os.path.join(root, "package.json")): sys.exit("No package.json there - pass the project root.")
    if not os.path.isfile(os.path.join(root, "src", "lib", "site-data.ts")): sys.exit("Install the previous redesign (install_keyhaven.py) first.")
    for rel, data in FILES.items():
        dst = os.path.join(root, *rel.split("/")); os.makedirs(os.path.dirname(dst), exist_ok=True)
        if os.path.exists(dst): shutil.copy2(dst, dst + ".bak")
        open(dst, "wb").write(zlib.decompress(base64.b64decode(data))); print("placed", rel)
    print("\nDone. Restart `npm run dev` if it was running.")
main()
